<template>
  <view class="modal-shade page-shade" @click.self="$emit('close')"><view class="modal share-modal" role="dialog" aria-modal="true" aria-label="分享学习 / Partager">
    <view class="modal-heading"><button hover-class="none" class="icon-button back-control" @click="$emit('close')" aria-label="返回 / Retour"><Icon name="back" /></button><Bi zh="学习分享" fr="Partager mes progrès" /></view>
    <view class="share-layout"><view class="poster-wrap"><image v-if="preview" :src="preview" class="poster-image" mode="widthFix" alt="中法双语学习分享卡片 / Carte de progression" /><Bi v-else zh="正在生成图片" fr="Création de l’image…" /></view>
    <view class="share-controls"><Bi zh="选择封面" fr="Choisir une couverture" /><view class="cover-choices"><button hover-class="none" v-for="t in themes" :key="t.id" :class="['cover-choice',{ selected: theme===t.id&&!custom }]" :aria-pressed="theme===t.id&&!custom" @click="theme=t.id;custom=null"><view :style="{backgroundImage:`url(${themePreview(t)})`}" /><Bi :zh="t.zh" :fr="t.fr" small /></button></view>
      <button hover-class="none" class="button secondary wide" @click="chooseCover"><Icon name="plus" /><Bi zh="选择自己的图片" fr="Utiliser une photo" /></button>
      <view v-if="custom" class="setting-stack photo-position"><Bi zh="图片位置" fr="Cadrage" small /><Bi zh="左右" fr="Horizontal" small /><slider :value="positionX" min="0" max="100" @changing="positionX=$event.detail.value" @change="positionX=$event.detail.value" activeColor="#6975ad" /><Bi zh="上下" fr="Vertical" small /><slider :value="position" min="0" max="100" @changing="position=$event.detail.value" @change="position=$event.detail.value" activeColor="#6975ad" /><Bi zh="缩放" fr="Zoom" small /><slider :value="zoom" min="100" max="200" @changing="zoom=$event.detail.value" @change="zoom=$event.detail.value" activeColor="#6975ad" /></view>
      <view v-if="showWords&&featuredWord" class="share-message"><Bi zh="今日新词" fr="Un nouveau mot du jour" small /><text lang="fr">{{ featuredWord.word }}</text><text>{{ featuredWord.pos }} · {{ featuredWord.meaning }}</text><button v-if="stats.newWords.length>1" hover-class="none" class="text-button" @click="wordIndex=(wordIndex+1)%stats.newWords.length"><Icon name="repeat" /><Bi zh="换个词" fr="Changer de mot" inline /></button></view>
      <view class="share-message"><Bi :zh="`名言 · ${quotes.length} 句`" :fr="`${quotes.length} citations`" small /><text lang="fr">{{ quotes[message].fr }}</text><text>{{ quotes[message].zh }}</text><text class="quote-credit">{{ quotes[message].author }} · {{ quotes[message].work }}</text><button hover-class="none" class="text-button" @click="message=randomQuoteIndex(message)"><Icon name="repeat" /><Bi zh="换一句" fr="Changer de citation" inline /></button></view>
      <button hover-class="none" class="toggle-row" @click="showWords=!showWords"><Bi zh="展示今日新词" fr="Afficher les nouveaux mots" small /><view :class="['toggle',{ on: showWords }]" /></button>
      <view class="share-lessons"><Bi zh="今日完成的 Lesson" fr="Leçons terminées aujourd’hui" small /><view v-if="stats.lessons?.length" class="share-lesson-options"><button hover-class="none" v-for="lesson in stats.lessons" :key="lesson.id" :class="['share-lesson-choice',{selected:selectedLessons.includes(lesson.id)}]" :aria-pressed="selectedLessons.includes(lesson.id)" @click="toggleLesson(lesson.id)"><Icon :name="selectedLessons.includes(lesson.id)?'check':'plus'" /><text>{{ lesson.label }}</text></button></view><Bi v-else zh="今天暂无新完成的 Lesson" fr="Aucune nouvelle leçon terminée aujourd’hui." small /></view>
      <view class="share-actions"><button hover-class="none" class="button secondary" :disabled="drawing" @click="save(false)"><Icon name="download" /><Bi zh="保存图片" fr="Enregistrer" /></button><button hover-class="none" class="button primary" :disabled="drawing" @click="save(true)"><Icon name="upload" /><Bi zh="分享" fr="Partager" /></button></view>
    </view></view>
  </view></view>
</template>
<script setup>
import { computed, ref, watch, onUnmounted } from 'vue'; import Bi from './Bi.vue'; import Icon from './Icon.vue';
import { themes, themePreview, drawPoster } from '../platform/poster.js'; import { chooseFile, download } from '../platform/files.js';
import {quotes,randomQuoteIndex} from '../domain/quotes.js';
import {nativeExport,nativeHost} from '../platform/native.js';
const props = defineProps({ stats: Object }); const emit = defineEmits(['close','notice']);
const theme=ref('galaxy'),message=ref(randomQuoteIndex()),wordIndex=ref(0),custom=ref(null),position=ref(50),positionX=ref(50),zoom=ref(100),showWords=ref(true),selectedLessons=ref([]),drawing=ref(false),preview=ref(null); let blob, serial=0, photoUrl;
const featuredWord=computed(()=>props.stats.newWords?.[wordIndex.value%props.stats.newWords.length]||null);
function toggleLesson(id){selectedLessons.value=selectedLessons.value.includes(id)?selectedLessons.value.filter(x=>x!==id):[...selectedLessons.value,id];}
async function draw(){const token=++serial;drawing.value=true;try{const b=await drawPoster({stats:props.stats,theme:theme.value,message:message.value,custom:custom.value,position:position.value,positionX:positionX.value,zoom:zoom.value,showWords:showWords.value,featuredWord:showWords.value?featuredWord.value:null,lessons:(props.stats.lessons||[]).filter(l=>selectedLessons.value.includes(l.id)).map(l=>l.label)});if(token!==serial)return;blob=b;if(preview.value)URL.revokeObjectURL(preview.value);preview.value=URL.createObjectURL(b);}catch{emit('notice','图片生成失败 / Impossible de créer l’image.');}finally{if(token===serial)drawing.value=false;}}
watch([theme,message,wordIndex,custom,position,positionX,zoom,showWords,selectedLessons,()=>props.stats],draw,{immediate:true});
async function chooseCover(){try{const f=await chooseFile('image/png,image/jpeg,image/webp');if(!f)return;if(f.size>10*1024*1024)throw new Error('图片不能超过 10 MB / Photo limitée à 10 Mo.');if(photoUrl)URL.revokeObjectURL(photoUrl);photoUrl=URL.createObjectURL(f);position.value=positionX.value=50;zoom.value=100;custom.value=photoUrl;}catch(e){emit('notice',e.message);}}
async function save(share){if(!blob||drawing.value)return;const name=`francais-${props.stats.date}.png`;try{if(nativeHost()){await nativeExport(name,new Uint8Array(await blob.arrayBuffer()),'image/png',share);if(!share)emit('notice','图片已保存 / Image enregistrée.');return;}const file=new File([blob],name,{type:'image/png'});if(share&&navigator.canShare?.({files:[file]})){await navigator.share({files:[file],title:'启航法语 · Cap sur le français'});}else{await download(name,new Uint8Array(await blob.arrayBuffer()),'image/png');emit('notice',share?'已保存图片，可从相册分享 / Image enregistrée, prête à partager.':'图片已保存 / Image enregistrée.');}}catch(e){if(e.name!=='AbortError')emit('notice','分享失败，请尝试保存图片 / Essayez d’enregistrer l’image.');}}
onUnmounted(()=>{serial++;if(preview.value)URL.revokeObjectURL(preview.value);if(photoUrl)URL.revokeObjectURL(photoUrl);});
</script>
